"""Authoring source. Output embeds into index.html; studying needs no Python."""
import json
from pathlib import Path

def A(answer, pitfall, followup, checks=None, code=None):
    result = dict(answer=answer, pitfall=pitfall, followup=followup,
                  checks=checks or [])
    if code:
        result['code'] = code
    return result

